    function activeFilterLabels(){const labels=[];if(search.value.trim())labels.push(`Meklēšana: ${search.value.trim()}`);if(selectedRetailer)labels.push(retailerName(selectedRetailer));if(sort.value!=="name")labels.push(sort.options[sort.selectedIndex]?.textContent||sort.value);if(mode==="deals"&&dealView==="upcoming")labels.push("Drīzumā");for(const [key,label] of Object.entries({app:"App",coupon:"Kupons",discount:"Atlaide",image:"Ar attēlu"}))if(featureState[key])labels.push(label);if(mode==="canonical"&&currentOnly.checked)labels.push("Tikai aktuālie");if(mode==="canonical"&&comparisonOnly.checked)labels.push("Tikai salīdzināmi");return labels;}function renderFilterSummary(){const labels=activeFilterLabels();filterSummary.innerHTML=labels.length?`<span class="filter-label">Aktīvie filtri</span>${labels.map(label=>`<span class="filter-token">${esc(label)}</span>`).join("")}<button class="reset-filters" id="resetFilters" type="button">Notīrīt filtrus</button>`:`<span class="muted">Nav papildu filtru.</span>`;$("resetFilters")?.addEventListener("click",resetFilters);if(activeFilterCount)activeFilterCount.textContent=`${labels.length} aktīvi`;}function resetFilters(){search.value="";selectedRetailer="";sort.value="name";currentOnly.checked=false;comparisonOnly.checked=false;dealView="current";for(const key of Object.keys(featureState))featureState[key]=false;retailers.querySelectorAll(".chip").forEach(c=>c.classList.toggle("active",(c.dataset.retailer||"")===""));if($("retailerSelect"))$("retailerSelect").value="";featureFilters.querySelectorAll(".chip").forEach(c=>c.classList.remove("active"));dealViewEl.querySelectorAll("[data-deal-view]").forEach(c=>c.classList.toggle("active",c.dataset.dealView==="current"));updateSearchClear();saveViewPrefs();syncUrl();renderFilterSummary();reloadAll();}
